 const message=(result.spacing?result.spacing+' entrelinha(s) corrigida(s); ':'')+(result.fonts?result.fonts+' tamanho(s) de fonte corrigido(s); ':'')+(result.lines?result.lines+' espessura(s) de linha corrigida(s); ':'')+result.labels+' rótulo(s) preparados em '+result.runs+' trechos posicionados; '+result.toggles+' caixas de seleção com o centro preservado; '+result.values+' valores de texto/data alinhados à Tela. Salve o layout no MV e compare a impressão. Ctrl+Z desfaz.'+(result.skipped.length?' '+result.skipped.length+' texto(s) preservados: '+result.skipped.join(' • '):'');
